package app.loki.figthere.dialogs

import androidx.compose.runtime.Composable
import kotlinx.serialization.json.JsonObject

// Generated by egui2compose: the dialogs translated from the desktop front end, for the app to
// open from wherever each belongs (a group's launcher, a menu entry, an engine request).

/**
 * [command] set: the menu opens that command's form (built from the engine's params doc) instead of [show].
 * [hidden]: the desktop dialog has no command to run, so the menu leaves it out; [show] is kept for when one is bound
 * (name it in dialog-commands.json and regenerate).
 */
class TranslatedDialog(val title: String, val source: String, val command: String? = null, val hidden: Boolean = false, val show: @Composable (onRun: (String, JsonObject) -> Unit, onDismiss: () -> Unit) -> Unit)

val TRANSLATED_DIALOGS: List<TranslatedDialog> = listOf(
    TranslatedDialog("Find and replace", "dialogs.rs") { onRun, onDismiss -> DialogsDialog(onRun, onDismiss) },
    TranslatedDialog("Batch rename batch rename dialog", "dialogs/batch_rename.rs") { onRun, onDismiss -> BatchRenameBatchRenameDialogDialog(onRun, onDismiss) },
    TranslatedDialog("Edit variable", "dialogs/variables_panel.rs") { onRun, onDismiss -> VariablesPanelDetailsDialog(onRun, onDismiss) },
    TranslatedDialog("Credits contributors in", "dialogs/credits.rs") { onRun, onDismiss -> CreditsContributorsInDialog(onRun, onDismiss) },
    TranslatedDialog("Plugins ui field", "dialogs/plugins_ui.rs", hidden = true) { onRun, onDismiss -> PluginsUiFieldDialog(onRun, onDismiss) },
    TranslatedDialog("Sampled color", "dialogs/sampled_color.rs") { onRun, onDismiss -> SampledColorDialog(onRun, onDismiss) },
    TranslatedDialog("Variables panel table", "dialogs/variables_panel.rs", hidden = true) { onRun, onDismiss -> VariablesPanelTableDialog(onRun, onDismiss) },
    TranslatedDialog("Variables panel value cell", "dialogs/variables_panel.rs") { onRun, onDismiss -> VariablesPanelValueCellDialog(onRun, onDismiss) },
)
